    edge1_t:'ब्रोकर, निर्माता नहीं', edge1_p:'हम वह नहीं बेचते जो हमारे पास है; हम वह ढूँढते हैं जिसकी आपको आवश्यकता है। हम खरीदार का प्रतिनिधित्व करते हुए सबसे उपयुक्त लॉट के लिए बाज़ार का विश्लेषण करते हैं।',
    edge2_t:'गुणवत्ता कवच', edge2_p:'कोई अस्पष्टता नहीं। जहाज़ पर लादे जाने से पहले हर लॉट की जाँच स्वतंत्र तृतीय-पक्ष निरीक्षकों और हमारी आंतरिक गुणवत्ता टीम द्वारा की जाती है। हम पहले सत्यापन करते हैं, फिर शिपमेंट भेजते हैं।',
    edge3_t:'स्रोत-स्थल की जानकारी', edge3_p:'चेन्नई, कोल्लम और डोंग नाई की हमारी टीमों से वास्तविक समय का डेटा मिलता है। हम कीमतों में उतार-चढ़ाव का पहले ही अनुमान लगा लेते हैं।',
    edge4_t:'लॉजिस्टिक्स परिशुद्धता', edge4_p:'एंड-टू-एंड दस्तावेज़ प्रबंधन। बिल ऑफ़ लैडिंग से फाइटोसैनिटरी प्रमाणपत्र तक, हम शून्य बंदरगाह देरी सुनिश्चित करते हैं।',
    quote_eyebrow:'ट्रेडिंग डेस्क', quote_h2:'सीधा बाज़ार कोटेशन प्राप्त करें', quote_p:'हमारे विश्लेषक वर्तमान फसल उपज और मूल्य के आधार पर लक्षित प्रस्ताव देते हैं।',
    f_company:'पंजीकृत कंपनी का नाम', f_company_ph:'कंपनी लि.', f_product:'आवश्यक वस्तु',
